    '-- Name: guard_user_roles_delete(); Type: FUNCTION; Schema: public; Owner: <normalized>\n'
    '--\n'
    '\n'
    'CREATE FUNCTION "public"."guard_user_roles_delete"() RETURNS "trigger"\n'
    '    LANGUAGE "plpgsql"\n'
    '    AS $$\n'
    '        BEGIN\n'
    "          IF current_setting('app.guard.authorized_deletion', true) IS DISTINCT FROM 'true' THEN\n"
    '            RAISE EXCEPTION\n'
    "              'Unauthorized DELETE on user_roles: '\n"
    "              'session GUC app.guard.authorized_deletion is not set to ''true''. '\n"
    "              'Use app.auth.deletion_guard.authorize_deletion() in the sanctioned service path.'\n"
    "              USING ERRCODE = '42501';\n"
    '          END IF;\n'
    '          RETURN OLD;\n'
    '        END;\n'
    '        $$;\n'
    '\n'
    '\n'
    '--\n'
    '-- Name: guard_users_delete(); Type: FUNCTION; Schema: public; Owner: <normalized>\n'
    '--\n'
    '\n'
    'CREATE FUNCTION "public"."guard_users_delete"() RETURNS "trigger"\n'
    '    LANGUAGE "plpgsql"\n'
    '    AS $$\n'
    '        BEGIN\n'
    "          IF current_setting('app.guard.authorized_deletion', true) IS DISTINCT FROM 'true' THEN\n"
    '            RAISE EXCEPTION\n'
    "              'Unauthorized DELETE on users: '\n"
    "              'session GUC app.guard.authorized_deletion is not set to ''true''. '\n"
    "              'Use app.auth.deletion_guard.authorize_deletion() in the sanctioned service path.'\n"
    "              USING ERRCODE = '42501';\n"
    '          END IF;\n'
    '          RETURN OLD;\n'
    '        END;\n'
    '        $$;\n'
    '\n'
    '\n'
    "SET default_tablespace = '';\n"
    '\n'
    'SET default_table_access_method = "heap";\n'
    '\n'
